-- ATLAS 005 — Total Environment relocated to its real address.
-- Deck said 'Mahadevapura'; the address is No.78 ITPL Main Road, EPIP Zone.
-- OSM way/1145006727. 4.46 km correction; all derived figures recomputed.
begin;

update properties set name='Total Environment — Imagine', lat=12.9876277, lng=77.7307563,
  coord_confirmed=true, coord_source='OSM way/1145006727 + operator-published address'
  where id='totalenv';

delete from property_competitors;


